package com.delivery.platform.catalog.branch.api;
import com.delivery.platform.catalog.common.CatalogSupport;import com.delivery.platform.common.ApiException;import com.delivery.platform.identity.security.IdentityPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.util.*;
@RestController public class BranchProductController {private final JdbcClient db;private final CatalogSupport support;public BranchProductController(JdbcClient d,CatalogSupport s){db=d;support=s;}public record Availability(UUID productId,String productName,boolean available,BigDecimal basePrice,BigDecimal overridePrice,BigDecimal effectivePrice,BigDecimal stockQuantity,Integer preparationTimeMinutes){}public record Save(boolean available,@DecimalMin("0")BigDecimal overridePrice,@DecimalMin("0")BigDecimal stockQuantity,@Min(0)Integer preparationTimeMinutes){}
 @GetMapping("/api/v1/branches/{branchId}/products") @PreAuthorize("hasAuthority('CATALOG_BRANCHES_VIEW')") public List<Availability> list(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID branchId){support.branch(p,branchId);return db.sql("select p.id,p.name,p.base_price,bp.available,bp.override_price,coalesce(bp.override_price,p.base_price) effective_price,bp.stock_quantity,bp.preparation_time_minutes from branches b join products p on p.merchant_id=b.merchant_id left join branch_products bp on bp.branch_id=b.id and bp.product_id=p.id where b.id=:b and p.tenant_id=:t and p.status<>'ARCHIVED' order by p.name").param("b",branchId).param("t",p.tenantId()).query((r,n)->new Availability(r.getObject(1,UUID.class),r.getString(2),r.getObject(4)==null||r.getBoolean(4),r.getBigDecimal(3),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7),(Integer)r.getObject(8))).list();}
 @PutMapping("/api/v1/branches/{branchId}/products/{productId}") @Transactional @PreAuthorize("hasAuthority('CATALOG_BRANCHES_UPDATE')") public Availability save(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID branchId,@PathVariable UUID productId,@Valid @RequestBody Save q){support.branch(p,branchId);support.product(p,productId);int same=db.sql("select count(*) from branches b join products p on p.merchant_id=b.merchant_id where b.id=:b and p.id=:p and b.tenant_id=:t").param("b",branchId).param("p",productId).param("t",p.tenantId()).query(Integer.class).single();if(same==0)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_BRANCH_PRODUCT","Producto y sucursal deben pertenecer al mismo comercio");db.sql("insert into branch_products(tenant_id,branch_id,product_id,available,override_price,stock_quantity,preparation_time_minutes) values(:t,:b,:p,:a,:o,:s,:m) on conflict(branch_id,product_id) do update set available=excluded.available,override_price=excluded.override_price,stock_quantity=excluded.stock_quantity,preparation_time_minutes=excluded.preparation_time_minutes,updated_at=now()").param("t",p.tenantId()).param("b",branchId).param("p",productId).param("a",q.available()).param("o",q.overridePrice()).param("s",q.stockQuantity()).param("m",q.preparationTimeMinutes()).update();support.audit(p,"PRODUCT_UPDATED","PRODUCT",productId);return list(p,branchId).stream().filter(x->x.productId().equals(productId)).findFirst().orElseThrow();}}
